// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _check(uint256 a, uint256 b) internal {
        vm.assume(a != b);
        try c.SetMinSum(a) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(b) {} catch { return; }
        assertTrue(c.MinSum() == a);
    }

    function testFuzz_check(uint256 a, uint256 b) public {
        _check(a, b);
    }

    receive() external payable {}
}
